def findLastAffected(numSystem: int, count: int) -> int:
    # Josephus：J(1) = 0, J(i) = (J(i-1) + K) % i
    # 从系统 0 开始数，第 K 个（ID 为 K-1）最先被感染，正好是标准 Josephus 的计数方式
    j = 0
    for i in range(2, numSystem + 1):
        j = (j + count) % i
    return j


if __name__ == "__main__":
    n, k = map(int, input().split())
    print(findLastAffected(n, k))

class Solution {
    int findLastAffected(int numSystem, int count) {
        long j = 0;
        for (int i = 2; i <= numSystem; i++) j = (j + count) % i;
        return (int) j;
    }
}

